$ErrorActionPreference = "Stop"

# ANDON WEB INDUSTRIAL - BOOTSTRAP AMBIENTE VIRGEM V10.5.1
# Execute este arquivo em PowerShell como Administrador.
# Esta versao NAO instala Git, Node.js, Docker Desktop nem PostgreSQL automaticamente.
# Ela instala o menu/installer oficial em C:\web-andon-industrial e abre o menu.

$BasePath = "C:\web-andon-industrial"
$TempPath = Join-Path $env:TEMP "andon-installer-v10-5-1"
$ZipPath = Join-Path $env:TEMP "ANDON_INSTALLER_V10_5_1_OFICIAL.zip"

function Write-Ok($m) { Write-Host "[OK] $m" -ForegroundColor Green }
function Write-Warn($m) { Write-Host "[AVISO] $m" -ForegroundColor Yellow }
function Write-Fail($m) { Write-Host "[FALHA] $m" -ForegroundColor Red }

$id = [Security.Principal.WindowsIdentity]::GetCurrent()
$principal = New-Object Security.Principal.WindowsPrincipal($id)
if (!$principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    Write-Fail "Execute este bootstrap como Administrador."
    exit 1
}

Write-Host "==================================================" -ForegroundColor Cyan
Write-Host " ANDON WEB INDUSTRIAL - BOOTSTRAP V10.5.1" -ForegroundColor Cyan
Write-Host "==================================================" -ForegroundColor Cyan
Write-Host ""

New-Item -ItemType Directory -Force $BasePath | Out-Null
Remove-Item $TempPath -Recurse -Force -ErrorAction SilentlyContinue
New-Item -ItemType Directory -Force $TempPath | Out-Null

$payload = @(
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
) -join ""
[IO.File]::WriteAllBytes($ZipPath, [Convert]::FromBase64String($payload))
Expand-Archive -Path $ZipPath -DestinationPath $TempPath -Force

$apply = Join-Path $TempPath "APLICAR_INSTALLER_V10_5_1.ps1"
if (!(Test-Path $apply)) {
    Write-Fail "Aplicador nao encontrado dentro do pacote extraido: $apply"
    exit 1
}

Write-Ok "Pacote oficial extraido em: $TempPath"
Write-Ok "Aplicando installer em: $BasePath"

powershell.exe -ExecutionPolicy Bypass -NoProfile -File $apply
exit $LASTEXITCODE
